129	pub fn load_changesets(root: &Path, cfg: &ResolvedConfig) -> Result<Vec<LoadedChangeset>, GraphError> {
130	    let (loaded, mut failures) = load_changesets_permissive(root, cfg)?;
131	    if !failures.is_empty() {
132	        let failure = failures.remove(0);
133	        return Err(GraphError::ParseChangeset {
134	            path: failure.path,
135	            source: failure.source,
136	        });
137	    }
138	    Ok(loaded)
139	}
