#!/bin/bash
# fixture helpers
export GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1
CAL=/Users/gabe/Projects/callisto/.claude/worktrees/macos-15-runners/target/debug/callisto
G=/usr/bin/git
newrepo() { rm -rf "$1"; mkdir -p "$1"; cd "$1"; $G init -q -b main; $G config user.email t@t; $G config user.name t; $G config commit.gpgsign false; $G config tag.gpgsign false; }
commit() { $G add -A; $G commit -qm "${1:-init}"; }
# npm workspace: root package.json with workspaces packages/*
npmroot() { printf '{\n  "name": "root",\n  "private": true,\n  "workspaces": ["packages/*"]\n}\n' > package.json; }
