17	/// Options governing how a version plan is applied to the workspace.
18	#[derive(Clone, Debug, Default)]
19	pub struct ApplyOptions {
20	    /// When true, regenerate each affected ecosystem's lockfile after applying, in transient mode too.
21	    pub refresh_lockfiles: bool,
22	    /// When true (snapshot mode), manifest mutations are written to disk
23	    /// but changelog prepends (step 7), changeset deletions (step 8), and
24	    /// git staging (step 11) are suppressed.
25	    pub transient: bool,
26	}
27	
28	/// The result of a successful [`apply_version_plan`] call, describing which paths were written and staged.
29	#[derive(Clone, Debug, Default)]
30	pub struct ApplyOutcome {
31	    /// One entry per lockfile refreshed by this apply; `None` when refresh was skipped or nothing ran.
32	    pub lockfile_refresh_results: Option<Vec<LockfileRefreshResult>>,
33	    /// Paths written and staged via `git add`, relative to the workspace root.
34	    pub staged: Vec<PathBuf>,
35	}
36	
37	#[derive(Debug, Default)]
38	pub(crate) struct ManifestWriteGroup {
39	    pub(crate) bump: Option<(usize, callisto_model::Version)>,
40	    pub(crate) rewrite_indices: Vec<usize>,
41	}
42	
43	#[derive(Debug, Default)]
44	pub(crate) struct ManifestWriteClassification {
45	    pub(crate) batched: BTreeMap<PathBuf, ManifestWriteGroup>,
46	    /// Root-manifest paths written exclusively through
47	    /// `WorkspaceCargoResolver` (`CargoWorkspacePackage`/
48	    /// `CargoWorkspaceDependency` targets), with no competing write to the
49	    /// same physical file through the `Manifest` trait's `open()` path.
50	    /// Consumed the same way as `batched`, but via `WorkspaceCargoResolver`
51	    /// instead of `open()` -- see `apply_version_plan`'s resolver-batched
52	    /// loop.
53	    pub(crate) resolver_batched: BTreeMap<PathBuf, ManifestWriteGroup>,
54	    /// Paths that receive writes through BOTH the `Manifest` trait and
55	    /// `WorkspaceCargoResolver` -- the mixed-routing data-loss/ordering
56	    /// hazard.
57	    /// Never batched on either side; each write is applied individually,
58	    /// strictly in plan order, exactly as before this change.
59	    pub(crate) excluded: BTreeSet<PathBuf>,
60	}
61	
62	pub(crate) fn classify_manifest_writes(plan: &VersionPlan) -> ManifestWriteClassification {
63	    let mut resolver_by_path: BTreeMap<PathBuf, ManifestWriteGroup> = BTreeMap::new();
64	    for (idx, bump) in plan.bumps.iter().enumerate() {
65	        for write in &bump.writes {
66	            if let VersionWriteTarget::CargoWorkspacePackage { root_manifest } = write {
67	                resolver_by_path.entry(root_manifest.clone()).or_default().bump = Some((idx, bump.to.clone()));
68	            }
69	        }
70	    }
71	    for (idx, rewrite) in plan.rewrites.iter().enumerate() {
72	        if let DepWriteTarget::CargoWorkspaceDependency { root_manifest } = &rewrite.key.target {
73	            resolver_by_path
74	                .entry(root_manifest.clone())
75	                .or_default()
76	                .rewrite_indices
77	                .push(idx);
78	        }
79	    }
80	
81	    let mut by_path: BTreeMap<PathBuf, ManifestWriteGroup> = BTreeMap::new();
82	    for (idx, bump) in plan.bumps.iter().enumerate() {
83	        for write in &bump.writes {
84	            if let VersionWriteTarget::Manifest(p) = write {
85	                by_path.entry(p.clone()).or_default().bump = Some((idx, bump.to.clone()));
86	            }
87	        }
88	    }
89	    for (idx, rewrite) in plan.rewrites.iter().enumerate() {
90	        if let DepWriteTarget::Manifest(p) = &rewrite.key.target {
91	            by_path.entry(p.clone()).or_default().rewrite_indices.push(idx);
92	        }
93	    }
94	
95	    let mut batched = BTreeMap::new();
96	    let mut excluded = BTreeSet::new();
97	    for (path, group) in by_path {
98	        if resolver_by_path.contains_key(&path) {
99	            excluded.insert(path);
100	        } else {
101	            batched.insert(path, group);
102	        }
103	    }
104	
105	    // Every path in `resolver_by_path` that isn't also mixed-routed
106	    // (present in `excluded`) is safe to batch into one
107	    // load/mutate*/persist cycle -- it's written exclusively through
108	    // WorkspaceCargoResolver, never through the Manifest trait.
109	    let resolver_batched: BTreeMap<PathBuf, ManifestWriteGroup> = resolver_by_path
110	        .into_iter()
111	        .filter(|(path, _)| !excluded.contains(path))
112	        .collect();
113	
114	    ManifestWriteClassification {
115	        batched,
116	        resolver_batched,
117	        excluded,
118	    }
119	}
120	
121	/// Whether `root/path` exists; a failure to look is an error, never "deleted".
122	fn path_exists(root: &Path, path: &Path) -> Result<bool, GraphError> {
123	    callisto_model::strict_fs::exists(&root.join(path)).map_err(|e| GraphError::ApplyIo {
124	        path: path.to_path_buf(),
125	        message: e.to_string(),
126	    })
127	}
128	
129	/// Writes `plan` to disk and stages the touched paths in git.
130	///
131	/// Every side effect here is unconditional -- whether to apply at all is
132	/// the caller's decision, which is why an [`ApplyPermit`] is required
133	/// rather than a `dry_run` bool: a bool carries no guarantee any caller
134	/// actually consulted it. A dry-run caller can't obtain a permit and
135	/// simply doesn't call this function; it reports `plan` instead.
136	///
137	/// # Errors
138	///
139	/// - A target the plan would write that cannot be written (missing, a directory, behind a symbolic link, unreadable
140	///   or in a directory that takes no new file); this is checked for every target before the first write.
141	/// - Manifest parse/write failures (malformed TOML/JSON, unsupported format).
142	/// - Git subprocess failures (`git add`/`git rm --cached` non-zero exit).
143	/// - I/O errors writing changelog sections or `pre.json`.
144	pub fn apply_version_plan<R: CommandRunner>(
145	    root: &Path,
146	    plan: &VersionPlan,
147	    runner: &R,
148	    opts: &ApplyOptions,
149	    permit: &ApplyPermit,
150	) -> Result<ApplyOutcome, GraphError> {
151	    let mut outcome = ApplyOutcome::default();
152	    let mut modified_paths = Vec::new();
153	    let mut deferred_deletions = Vec::new();
154	
155	    let ctx = OpenContext::for_workspace_root(root)?;
156	    preflight::check(root, plan, opts, permit, runner)?;
157	    let active_ecosystems = active_ecosystems(plan);
158	    // Resolved before the first write, so a workspace that cannot be found stops the run with nothing changed.
159	    let cargo_workspaces = if active_ecosystems.contains(&Ecosystem::Cargo) {
160	        touched_cargo_workspaces(root, plan)?
161	    } else {
162	        BTreeSet::new()
163	    };
164	    let lockfile_dirs = lockfile_dirs(root, plan, &active_ecosystems)?;
165	    let classification = classify_manifest_writes(plan);
166	
167	    for step in write_steps(plan, &classification) {
168	        modified_paths.push(apply_write_step(&step, plan, root, &ctx, permit)?);
169	    }
170	
171	    if !opts.transient {
172	        for cl in &plan.changelog_writes {
173	            let rendered = crate::changelog::render_section(&cl.input)?;
174	            crate::changelog::prepend(
175	                root,
176	                &cl.changelog_path,
177	                &cl.input.package.display_name(),
178	                &rendered,
179	                permit,
180	            )?;
181	            modified_paths.push(cl.changelog_path.clone());
182	        }
183	
184	        for cs_path in &plan.consumed_changesets {
185	            deferred_deletions.push(cs_path.clone());
186	        }
187	
188	        if let Some(ref pre_state) = plan.pre_state_update {
189	            // Written from `plan.pre_json_path`, not derived from `consumed_changesets` (always empty in pre mode).
190	            let rel_pre_path = plan.pre_json_path.clone();
191	            let pre_path = root.join(&rel_pre_path);
192	            let text = match &plan.pre_json_original_text {
193	                Some(existing) => callisto_model::format::write_pre_json_preserving(pre_state, existing),
194	                None => callisto_model::format::write_pre_json(pre_state),
195	            };
196	            callisto_manifests::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| GraphError::ApplyIo {
197	                path: rel_pre_path.clone(),
198	                message: e.to_string(),
199	            })?;
200	            modified_paths.push(rel_pre_path);
201	        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
202	            deferred_deletions.push(rel_pre_path.clone());
203	        }
204	    }
205	
206	    // Must run before the staging loop below, so refreshed lockfiles are on disk to be staged.
207	    if opts.refresh_lockfiles {
208	        let refresh_results = refresh_lockfiles(runner, root, &cargo_workspaces, &lockfile_dirs)?;
209	        if !refresh_results.is_empty() {
210	            outcome.lockfile_refresh_results = Some(refresh_results);
211	        }
212	    }
213	
214	    // Stage each lockfile of an active ecosystem that exists beside the workspace the plan wrote into.
215	    let beside = |dirs: &BTreeSet<PathBuf>, names: &[&str]| -> Vec<PathBuf> {
216	        dirs.iter()
217	            .flat_map(|dir| names.iter().map(move |name| dir.join(name)))
218	            .collect()
219	    };
220	    let candidates = beside(&lockfile_dirs.npm, &NPM_LOCKFILES)
221	        .into_iter()
222	        .chain(beside(&lockfile_dirs.pypi, &PYPI_LOCKFILES));
223	    let mut lockfile_paths: Vec<PathBuf> = Vec::new();
224	    for p in candidates {
225	        if path_exists(root, &p)? && !modified_paths.contains(&p) {
226	            lockfile_paths.push(p.clone());
227	            modified_paths.push(p);
228	        }
229	    }
230	    for lockfile in cargo_workspaces.iter().map(|workspace| cargo_lockfile(workspace)) {
231	        if path_exists(root, &lockfile)? && !modified_paths.contains(&lockfile) {
232	            lockfile_paths.push(lockfile.clone());
233	            modified_paths.push(lockfile);
234	        }
235	    }
236	
237	    // A lockfile that a .gitignore ignores (a library's `Cargo.lock`, say) is not meant to be committed: refreshed on disk,
238	    // never staged. Anything else the plan stages was checked before the first write.
239	    if !opts.transient {
240	        let ignored = preflight::ignored_paths(runner, root, &lockfile_paths)?;
241	        modified_paths.retain(|path| !ignored.contains(path));
242	    }
243	
244	    if !opts.transient && (!modified_paths.is_empty() || !deferred_deletions.is_empty()) {
245	        // Stage all written release state before consuming its inputs. If a refresh or add fails,
246	        // the changesets/pre-state remain available; if removal staging fails, the manifest diff
247	        // still identifies the interrupted run.
248	        let mut existing = Vec::new();
249	        let mut deleted = Vec::new();
250	        for path in &modified_paths {
251	            if path_exists(root, path)? {
252	                existing.push(path);
253	            } else {
254	                deleted.push(path);
255	            }
256	        }
257	
258	        if !existing.is_empty() {
259	            run_git_on_paths(runner, root, &["add", "--"], &existing)?;
260	        }
261	
262	        if !deleted.is_empty() {
263	            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deleted)?;
264	        }
265	
266	        if !deferred_deletions.is_empty() {
267	            let deferred: Vec<&PathBuf> = deferred_deletions.iter().collect();
268	            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deferred)?;
269	
270	            // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
271	            for path in &deferred_deletions {
272	                match fs::remove_file(root.join(path)) {
273	                    Ok(()) => {}
274	                    Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
275	                    Err(e) => {
276	                        return Err(GraphError::ApplyIo {
277	                            path: path.clone(),
278	                            message: e.to_string(),
279	                        })
280	                    }
281	                }
282	            }
283	            modified_paths.extend(deferred_deletions.iter().cloned());
284	        }
285	
286	        outcome.staged = modified_paths;
287	    }
288	
289	    Ok(outcome)
290	}
291	
292	/// One physical write of a version plan, in the order it must happen.
293	enum WriteStep<'p> {
294	    /// One load/mutate/persist cycle over a manifest only the `Manifest` trait writes: the
295	    /// version bump (idempotency-guarded) first, then every dependency rewrite, one persist.
296	    Manifest {
297	        path: &'p PathBuf,
298	        group: &'p ManifestWriteGroup,
299	    },
300	    /// The same cycle for a Cargo workspace root only the `WorkspaceCargoResolver` writes. Its
301	    /// writes carry no idempotency precondition.
302	    WorkspaceRoot {
303	        root_manifest: &'p PathBuf,
304	        group: &'p ManifestWriteGroup,
305	    },
306	    /// Mixed-routing manifests (written through both routes) are never batched: each write is
307	    /// its own load/persist, strictly in plan order.
308	    MixedManifestVersion {
309	        path: &'p PathBuf,
310	        bump: &'p PlannedBump,
311	    },
312	    MixedWorkspaceVersion {
313	        root_manifest: &'p PathBuf,
314	        to: &'p Version,
315	    },
316	    MixedManifestRewrite {
317	        path: &'p PathBuf,
318	        rewrite: &'p SpecRewrite,
319	    },
320	    MixedWorkspaceRewrite {
321	        root_manifest: &'p PathBuf,
322	        rewrite: &'p SpecRewrite,
323	    },
324	    PlatformVersion(&'p PlatformWrite),
325	    OptionalDependencies(&'p OptionalDepUpdate),
326	}
327	
328	/// Orders every manifest write once, so execution is a single `match` and the per-file order
329	/// (bump, then rewrites, then one persist) is data rather than control flow.
330	fn write_steps<'p>(plan: &'p VersionPlan, classification: &'p ManifestWriteClassification) -> Vec<WriteStep<'p>> {
331	    let mut steps = Vec::new();
332	    for (path, group) in &classification.batched {
333	        steps.push(WriteStep::Manifest { path, group });
334	    }
335	    for (root_manifest, group) in &classification.resolver_batched {
336	        steps.push(WriteStep::WorkspaceRoot { root_manifest, group });
337	    }
338	    for bump in &plan.bumps {
339	        for write in &bump.writes {
340	            match write {
341	                VersionWriteTarget::Manifest(path) if classification.excluded.contains(path) => {
342	                    steps.push(WriteStep::MixedManifestVersion { path, bump });
343	                }
344	                VersionWriteTarget::CargoWorkspacePackage { root_manifest }
345	                    if !classification.resolver_batched.contains_key(root_manifest) =>
346	                {
347	                    steps.push(WriteStep::MixedWorkspaceVersion {
348	                        root_manifest,
349	                        to: &bump.to,
350	                    });
351	                }
352	                _ => {}
353	            }
354	        }
355	    }
356	    for rewrite in &plan.rewrites {
357	        match &rewrite.key.target {
358	            DepWriteTarget::Manifest(path) if classification.excluded.contains(path) => {
359	                steps.push(WriteStep::MixedManifestRewrite { path, rewrite });
360	            }
361	            DepWriteTarget::CargoWorkspaceDependency { root_manifest }
362	                if !classification.resolver_batched.contains_key(root_manifest) =>
363	            {
364	                steps.push(WriteStep::MixedWorkspaceRewrite { root_manifest, rewrite });
365	            }
366	            _ => {}
367	        }
368	    }
369	    steps.extend(plan.platform_writes.iter().map(WriteStep::PlatformVersion));
370	    steps.extend(plan.optional_dep_updates.iter().map(WriteStep::OptionalDependencies));
371	    steps
372	}
373	
374	/// Performs one step and returns the path to stage.
375	fn apply_write_step(
376	    step: &WriteStep<'_>,
377	    plan: &VersionPlan,
378	    root: &Path,
379	    ctx: &OpenContext<'_>,
380	    permit: &ApplyPermit,
381	) -> Result<PathBuf, GraphError> {
382	    match step {
383	        WriteStep::Manifest { path, group } => {
384	            let mut handle = open_canonical(path, ctx)?;
385	            let mut mutated = false;
386	            if let Some((bump_idx, target_version)) = &group.bump {
387	                let bump = &plan.bumps[*bump_idx];
388	                mutated = write_version_guarded(handle.as_mut(), path, &bump.from, target_version, permit)?;
389	            }
390	            for rewrite_idx in &group.rewrite_indices {
391	                rewrite_dependency(handle.as_mut(), &plan.rewrites[*rewrite_idx], permit)?;
392	                mutated = true;
393	            }
394	            if mutated {
395	                handle.persist(permit)?;
396	            }
397	            Ok((*path).clone())
398	        }
399	        WriteStep::WorkspaceRoot { root_manifest, group } => {
400	            let mut ws_res = WorkspaceCargoResolver::load_at(root, root_manifest)?;
401	            let mut mutated = false;
402	            if let Some((_, target_version)) = &group.bump {
403	                ws_res.write_version(target_version, permit)?;
404	                mutated = true;
405	            }
406	            for rewrite_idx in &group.rewrite_indices {
407	                let rewrite = &plan.rewrites[*rewrite_idx];
408	                ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
409	                mutated = true;
410	            }
411	            if mutated {
412	                ws_res.persist(permit)?;
413	            }
414	            Ok((*root_manifest).clone())
415	        }
416	        WriteStep::MixedManifestVersion { path, bump } => {
417	            let mut handle = open_canonical(path, ctx)?;
418	            if write_version_guarded(handle.as_mut(), path, &bump.from, &bump.to, permit)? {
419	                handle.persist(permit)?;
420	            }
421	            Ok((*path).clone())
422	        }
423	        WriteStep::MixedWorkspaceVersion { root_manifest, to } => {
424	            let mut ws_res = WorkspaceCargoResolver::load_at(root, root_manifest)?;
425	            ws_res.write_version(to, permit)?;
426	            ws_res.persist(permit)?;
427	            Ok((*root_manifest).clone())
428	        }
429	        WriteStep::MixedManifestRewrite { path, rewrite } => {
430	            let mut handle = open_canonical(path, ctx)?;
431	            rewrite_dependency(handle.as_mut(), rewrite, permit)?;
432	            handle.persist(permit)?;
433	            Ok((*path).clone())
434	        }
435	        WriteStep::MixedWorkspaceRewrite { root_manifest, rewrite } => {
436	            let mut ws_res = WorkspaceCargoResolver::load_at(root, root_manifest)?;
437	            ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
438	            ws_res.persist(permit)?;
439	            Ok((*root_manifest).clone())
440	        }
441	        WriteStep::PlatformVersion(write) => {
442	            let mut handle = open_canonical(&write.manifest, ctx)?;
443	            if write_version_guarded(handle.as_mut(), &write.manifest, &write.from, &write.version, permit)? {
444	                handle.persist(permit)?;
445	            }
446	            Ok(write.manifest.clone())
447	        }
448	        WriteStep::OptionalDependencies(update) => {
449	            let mut handle = open_canonical(&update.manifest, ctx)?;
450	            handle.update_optional_dependencies(&update.updates, permit)?;
451	            handle.persist(permit)?;
452	            Ok(update.manifest.clone())
453	        }
454	    }
455	}
456	
457	fn open_canonical(path: &Path, ctx: &OpenContext<'_>) -> Result<Box<dyn Manifest>, GraphError> {
458	    let fmt = callisto_model::ManifestFormat::from_path(path)?;
459	    let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
460	    Ok(open(&decl, ctx)?)
461	}
462	
463	/// Writes `to` unless the manifest already has it, and refuses any version other than `from`:
464	/// the precondition that makes re-running an interrupted apply safe. Returns whether it wrote.
465	fn write_version_guarded(
466	    handle: &mut dyn Manifest,
467	    path: &Path,
468	    from: &Version,
469	    to: &Version,
470	    permit: &ApplyPermit,
471	) -> Result<bool, GraphError> {
472	    let current = handle.current_version()?;
473	    if current == *to {
474	        return Ok(false);
475	    }
476	    if current != *from {
477	        return Err(GraphError::UnexpectedManifestVersion {
478	            path: path.to_path_buf(),
479	            expected_from: from.clone(),
480	            expected_to: to.clone(),
481	            found: current,
482	        });
483	    }
484	    handle.write_version(to, permit)?;
485	    Ok(true)
486	}
487	
488	fn rewrite_dependency(
489	    handle: &mut dyn Manifest,
490	    rewrite: &SpecRewrite,
491	    permit: &ApplyPermit,
492	) -> Result<(), GraphError> {
493	    handle.update_dependency_spec(
494	        &rewrite.key.name,
495	        rewrite.key.kind.unwrap_or(DepKind::Runtime),
496	        &rewrite.key.locator,
497	        rewrite.to.clone(),
498	        permit,
499	    )?;
500	    Ok(())
501	}
502	
503	/// The root manifest of each Cargo workspace the plan writes into. Each has its own `Cargo.lock` beside it.
504	fn touched_cargo_workspaces(root: &Path, plan: &VersionPlan) -> Result<BTreeSet<PathBuf>, GraphError> {
505	    let mut workspaces = BTreeSet::new();
506	    for write in plan.bumps.iter().flat_map(|bump| &bump.writes) {
507	        if let VersionWriteTarget::CargoWorkspacePackage { root_manifest } = write {
508	            workspaces.insert(root_manifest.clone());
509	        }
510	    }
511	    for rewrite in &plan.rewrites {
512	        if let DepWriteTarget::CargoWorkspaceDependency { root_manifest } = &rewrite.key.target {
513	            workspaces.insert(root_manifest.clone());
514	        }
515	    }
516	    let members = written_manifests(plan);
517	    let mut reads = callisto_manifests::WorkspaceReads::default();
518	    for member in members {
519	        if ManifestFormat::from_path(member) == Ok(ManifestFormat::CargoToml) {
520	            workspaces.insert(callisto_manifests::cargo_workspace_of(&mut reads, root, member)?);
521	        }
522	    }
523	    if workspaces.is_empty() {
524	        // Nothing names a workspace: a Cargo package was bumped without a manifest write of its own.
525	        workspaces.insert(PathBuf::from("Cargo.toml"));
526	    }
527	    Ok(workspaces)
528	}
529	
530	/// Every manifest, other than a Cargo workspace root, the plan writes to.
531	fn written_manifests(plan: &VersionPlan) -> Vec<&Path> {
532	    let mut manifests: Vec<&Path> = Vec::new();
533	    for write in plan.bumps.iter().flat_map(|bump| &bump.writes) {
534	        if let VersionWriteTarget::Manifest(path) = write {
535	            manifests.push(path);
536	        }
537	    }
538	    for rewrite in &plan.rewrites {
539	        if let DepWriteTarget::Manifest(path) = &rewrite.key.target {
540	            manifests.push(path);
541	        }
542	    }
543	    manifests.extend(plan.platform_writes.iter().map(|write| write.manifest.as_path()));
544	    manifests.extend(plan.optional_dep_updates.iter().map(|update| update.manifest.as_path()));
545	    manifests
546	}
547	
548	/// The lockfile beside a Cargo workspace root manifest.
549	fn cargo_lockfile(root_manifest: &Path) -> PathBuf {
550	    root_manifest.with_file_name("Cargo.lock")
551	}
552	
553	/// The ecosystems a plan touches, so only their lockfiles are refreshed and staged. Staging
554	/// the lockfile of an untouched ecosystem could sweep up unrelated user changes.
555	fn active_ecosystems(plan: &VersionPlan) -> HashSet<Ecosystem> {
556	    let of_manifest = |path: &Path| ManifestFormat::from_path(path).ok().map(|fmt| fmt.ecosystem());
557	    let mut active = HashSet::new();
558	    for bump in &plan.bumps {
559	        active.extend(bump.package.ecosystem());
560	        for write in &bump.writes {
561	            active.extend(match write {
562	                VersionWriteTarget::CargoWorkspacePackage { .. } => Some(Ecosystem::Cargo),
563	                VersionWriteTarget::Manifest(path) => of_manifest(path),
564	            });
565	        }
566	    }
567	    for rewrite in &plan.rewrites {
568	        active.extend(match &rewrite.key.target {
569	            DepWriteTarget::CargoWorkspaceDependency { .. } => Some(Ecosystem::Cargo),
570	            DepWriteTarget::Manifest(path) => of_manifest(path),
571	        });
572	    }
573	    active.extend(
574	        plan.platform_writes
575	            .iter()
576	            .filter_map(|write| of_manifest(&write.manifest)),
577	    );
578	    active.extend(
579	        plan.optional_dep_updates
580	            .iter()
581	            .filter_map(|update| of_manifest(&update.manifest)),
582	    );
583	    active
584	}
585	
586	/// Runs `git <prefix> <paths...>` in `root`, mapping a non-zero exit to `GraphError::Command`.
587	fn run_git_on_paths<R: CommandRunner>(
588	    runner: &R,
589	    root: &Path,
590	    prefix: &[&str],
591	    paths: &[&PathBuf],
592	) -> Result<(), GraphError> {
593	    let rendered: Vec<String> = paths.iter().map(|p| p.display().to_string()).collect();
594	    let mut args: Vec<&str> = prefix.to_vec();
595	    args.extend(rendered.iter().map(String::as_str));
596	    let output = runner.run("git", &args, root)?;
597	    if !output.success() {
598	        return Err(GraphError::Command(CommandError::Failed {
599	            program: "git".to_string(),
600	            exit_code: output.exit_code,
601	            stderr: output.redacted_stderr(),
602	        }));
603	    }
604	    Ok(())
605	}
606	
607	/// Regenerates the lockfile of each active ecosystem with the ecosystem's own tool. For Python,
608	/// exactly one lockfile is refreshed, in uv, poetry, pdm order.
609	fn refresh_lockfiles<R: CommandRunner>(
610	    runner: &R,
611	    root: &Path,
612	    cargo_workspaces: &BTreeSet<PathBuf>,
613	    lockfile_dirs: &LockfileDirs,
614	) -> Result<Vec<LockfileRefreshResult>, GraphError> {
615	    let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();
616	
617	    for workspace in cargo_workspaces {
618	        let lockfile = cargo_lockfile(workspace);
619	        refresh_results.push(run_lockfile_refresh(
620	            runner,
621	            &root.join(workspace.parent().unwrap_or(Path::new(""))),
622	            &lockfile.to_string_lossy(),
623	            "cargo",
624	            &["update", "--workspace"],
625	        )?);
626	    }
627	
628	    for dir in &lockfile_dirs.pypi {
629	        for (file, program, args) in PYPI_REFRESH {
630	            if path_exists(root, &dir.join(file))? {
631	                refresh_results.push(refresh_in(runner, root, dir, file, program, args)?);
632	                break;
633	            }
634	        }
635	    }
636	
637	    for dir in &lockfile_dirs.npm {
638	        for (file, program, args) in NPM_REFRESH {
639	            if path_exists(root, &dir.join(file))? {
640	                refresh_results.push(refresh_in(runner, root, dir, file, program, args)?);
641	            }
642	        }
643	        for file in ["bun.lock", "bun.lockb"] {
644	            if path_exists(root, &dir.join(file))? {
645	                refresh_results.push(refresh_in(
646	                    runner,
647	                    root,
648	                    dir,
649	                    file,
650	                    "bun",
651	                    &["install", "--lockfile-only"],
652	                )?);
653	                break;
654	            }
655	        }
656	    }
657	
658	    Ok(refresh_results)
659	}
660	
661	type Refresh = (&'static str, &'static str, &'static [&'static str]);
662	
663	/// For Python exactly one lockfile is refreshed per directory, in this order.
664	const PYPI_REFRESH: [Refresh; 3] = [
665	    ("uv.lock", "uv", &["lock"]),
666	    ("poetry.lock", "poetry", &["lock", "--no-update"]),
667	    ("pdm.lock", "pdm", &["lock", "--update-reuse"]),
668	];
669	
670	/// Each npm-family lockfile present is refreshed independently (bun's two spellings are handled apart).
671	const NPM_REFRESH: [Refresh; 3] = [
672	    (
673	        "package-lock.json",
674	        "npm",
675	        &["install", "--package-lock-only", "--ignore-scripts"],
676	    ),
677	    ("pnpm-lock.yaml", "pnpm", &["install", "--lockfile-only"]),
678	    ("yarn.lock", "yarn", &["install", "--mode", "update-lockfile"]),
679	];
680	
681	/// Runs the refresh of `dir/file` in `dir`, reporting the lockfile by its path from the workspace root.
682	fn refresh_in<R: CommandRunner>(
683	    runner: &R,
684	    root: &Path,
685	    dir: &Path,
686	    file: &str,
687	    program: &str,
688	    args: &[&str],
689	) -> Result<LockfileRefreshResult, GraphError> {
690	    run_lockfile_refresh(
691	        runner,
692	        &root.join(dir),
693	        &dir.join(file).to_string_lossy(),
694	        program,
695	        args,
696	    )
697	}
698	
699	/// The workspace directories, relative to the workspace root, whose npm-family and Python lockfiles the plan's writes
700	/// affect: each package's owning workspace, so one below the root keeps its own.
701	#[derive(Default)]
702	struct LockfileDirs {
703	    npm: BTreeSet<PathBuf>,
704	    pypi: BTreeSet<PathBuf>,
705	}
706	
707	fn lockfile_dirs(
708	    root: &Path,
709	    plan: &VersionPlan,
710	    active_ecosystems: &HashSet<Ecosystem>,
711	) -> Result<LockfileDirs, GraphError> {
712	    let mut dirs = LockfileDirs::default();
713	    for manifest in written_manifests(plan) {
714	        match ManifestFormat::from_path(manifest)
715	            .ok()
716	            .map(|format| format.ecosystem())
717	        {
718	            Some(Ecosystem::Npm) => {
719	                dirs.npm.insert(npm_workspace_dir(root, package_dir_of(manifest))?);
720	            }
721	            Some(Ecosystem::Pypi) => {
722	                dirs.pypi.insert(python_workspace_dir(root, package_dir_of(manifest))?);
723	            }
724	            _ => {}
725	        }
726	    }
727	    // A plan that names an ecosystem but writes none of its manifests refreshes the workspace root's lockfile.
728	    if active_ecosystems.contains(&Ecosystem::Npm) && dirs.npm.is_empty() {
729	        dirs.npm.insert(PathBuf::new());
730	    }
731	    if active_ecosystems.contains(&Ecosystem::Pypi) && dirs.pypi.is_empty() {
732	        dirs.pypi.insert(PathBuf::new());
733	    }
734	    Ok(dirs)
735	}
736	
737	/// The directory of a package whose manifest is `manifest`.
738	fn package_dir_of(manifest: &Path) -> &Path {
739	    manifest.parent().unwrap_or(Path::new(""))
740	}
741	
742	/// Maps a non-zero exit to `GraphError::LockfileRefreshFailed`, an exec failure to `GraphError::Command`.
743	fn run_lockfile_refresh<R: CommandRunner>(
744	    runner: &R,
745	    root: &Path,
746	    filename: &str,
747	    program: &str,
748	    args: &[&str],
749	) -> Result<LockfileRefreshResult, GraphError> {
750	    let refresh_command = format!("{program} {}", args.join(" "));
751	    let out = runner.run(program, args, root)?;
752	    if !out.success() {
753	        return Err(GraphError::LockfileRefreshFailed {
754	            filename: PathBuf::from(filename),
755	            refresh_command,
756	            exit_code: out.exit_code,
757	            stderr: out.redacted_stderr(),
758	        });
759	    }
760	    Ok(LockfileRefreshResult {
761	        filename: PathBuf::from(filename),
762	        refresh_command,
763	        success: true,
764	        exit_code: out.exit_code,
765	    })
766	}
