311	/// Refuses when a canonical manifest version differs from `HEAD` while release inputs remain or the change is staged.
312	pub fn check_partial_run<R: CommandRunner, D: DependencyResolver>(ws: &Workspace<'_, R, D>) -> Result<(), GraphError> {
313	    let head = match ws.git_access().head_sha() {
314	        Ok(head) => head,
315	        Err(error) => {
316	            let output = ws
317	                .runner
318	                .run("git", &["rev-parse", "--verify", "--quiet", "HEAD"], &ws.root)
319	                .map_err(GraphError::Command)?;
320	            match output.exit_code {
321	                Some(1) => return Ok(()),
322	                Some(0) => return Err(error.into()),
323	                exit_code => {
324	                    return Err(GraphError::Command(callisto_model::CommandError::Failed {
325	                        program: "git".to_string(),
326	                        exit_code,
327	                        stderr: output.stderr,
328	                    }))
329	                }
330	            }
331	        }
332	    };
333	    let head = head.as_str();
334	
335	    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
336	    let pre_mode = {
337	        let path = ws.root.join(ws.config.pre_json_path());
338	        let text = callisto_model::strict_fs::read_optional(&path)
339	            .map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
340	        if let Some(text) = text {
341	            let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
342	            Some(state.mode)
343	        } else {
344	            None
345	        }
346	    };
347	    let in_pre_release_cycle = pre_mode == Some(callisto_model::format::PreMode::Pre);
348	
349	    let changed = SourceChanges::since(ws, head)?;
350	    // The paths that can set each manifest's version are found once and used by both passes below.
351	    let mut sources: HashMap<std::path::PathBuf, Vec<String>> = HashMap::new();
352	    let staged_manifests = if in_pre_release_cycle {
353	        BTreeSet::new()
354	    } else {
355	        canonical_manifest_staged_paths(ws, head, &changed, &mut sources)?
356	    };
357	    let pending = !in_pre_release_cycle
358	        && (head_has_pending_changeset(ws, head)?
359	            || working_tree_has_pending_changeset(ws)?
360	            || !staged_manifests.is_empty());
361	    if !pending {
362	        return Ok(());
363	    }
364	
365	    let head_texts = RefCell::new(HashMap::new());
366	    let index_texts = RefCell::new(HashMap::new());
367	    prefetch_head_manifests(ws, head, &head_texts)?;
368	    let mut head_reads = callisto_manifests::WorkspaceReads::default();
369	    let mut index_reads = callisto_manifests::WorkspaceReads::default();
370	    let base_versions = ws.base_versions()?;
371	    for pkg in ws.graph.packages() {
372	        let Some(disk) = base_versions.get(&pkg.id) else {
373	            continue;
374	        };
375	        for decl in pkg.canonical_manifests() {
376	            let path = super::release_decision::normalized_git_path(&decl.path)?;
377	            let Some(head_version) = manifest_version_at(ws, head, &path, &head_texts, &mut head_reads)? else {
378	                continue;
379	            };
380	            let index_path_changed = version_sources(ws, head, &changed, decl, &mut sources)?
381	                .iter()
382	                .any(|source| staged_manifests.contains(source));
383	            let index_version = if index_path_changed {
384	                manifest_version_in_index(ws, head, &path, &index_texts, &mut index_reads)?
385	            } else {
386	                None
387	            };
388	            let index_display = match &index_version {
389	                Some(version) => version.version.render().to_string(),
390	                None if index_path_changed => "absent".to_string(),
391	                None => head_version.version.render().to_string(),
392	            };
393	            let index_differs = index_path_changed
394	                && index_version
395	                    .as_ref()
396	                    .is_none_or(|version| version.version != head_version.version);
397	            let completing_prerelease = pre_mode == Some(callisto_model::format::PreMode::Exit)
398	                && disk.is_prerelease()
399	                && (!index_path_changed
400	                    || index_version
401	                        .as_ref()
402	                        .is_some_and(|version| version.version.is_prerelease()));
403	            if completing_prerelease {
404	                continue;
405	            }
406	            if *disk != head_version.version || index_differs {
407	                return Err(GraphError::PartialVersionRun {
408	                    path: head_version.authority,
409	                    disk: disk.clone(),
410	                    index: index_display,
411	                    head: head_version.version,
412	                });
413	            }
414	        }
415	    }
416	
417	    Ok(())
418	}
