420	/// Reads every canonical manifest at `head` in one `git cat-file --batch`, so the version reads that follow cost no
421	/// process each. A failed batch is not an error: those reads then run one at a time, as they always could.
422	fn prefetch_head_manifests<R: CommandRunner, D: DependencyResolver>(
423	    ws: &Workspace<'_, R, D>,
424	    head: &str,
425	    texts: &ManifestTexts,
426	) -> Result<(), GraphError> {
427	    let mut paths = BTreeSet::new();
428	    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
429	        paths.insert(super::release_decision::normalized_git_path(&decl.path)?);
430	    }
431	    let objects: Vec<String> = paths.iter().map(|path| format!("{head}:{path}")).collect();
432	    let Ok(blobs) = batch_blobs(ws.runner, &ws.root, &objects) else {
433	        return Ok(());
434	    };
435	    let mut texts = texts.borrow_mut();
436	    for (path, blob) in paths.into_iter().zip(blobs) {
437	        texts.insert(
438	            path,
439	            match blob {
440	                BatchBlob::Blob(text) => Some(text),
441	                BatchBlob::Missing => None,
442	            },
443	        );
444	    }
445	    Ok(())
446	}
