448	/// True when an untracked or tracked changeset remains in the configured directory on disk.
449	fn working_tree_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
450	    ws: &Workspace<'_, R, D>,
451	) -> Result<bool, GraphError> {
452	    let dir = ws.root.join(&ws.config.changesets_dir);
453	    let files = crate::aggregate::list_changeset_files(&dir).map_err(|error| GraphError::ApplyIo {
454	        path: ws.config.changesets_dir.clone(),
455	        message: error.to_string(),
456	    })?;
457	    Ok(!files.is_empty())
