460	/// True when a canonical manifest differs between index and HEAD: `git add`ed by a prior `apply` but never committed.
461	fn canonical_manifest_staged_paths<R: CommandRunner, D: DependencyResolver>(
462	    ws: &Workspace<'_, R, D>,
463	    head: &str,
464	    changed: &SourceChanges,
465	    sources: &mut HashMap<std::path::PathBuf, Vec<String>>,
466	) -> Result<BTreeSet<String>, GraphError> {
467	    let mut paths = BTreeSet::new();
468	    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
469	        paths.extend(version_sources(ws, head, changed, decl, sources)?);
470	    }
471	    // The index-versus-HEAD diff `SourceChanges` already read answers this for every path at once.
472	    Ok(paths.into_iter().filter(|path| changed.staged.contains(path)).collect())
473	}
