475	/// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
476	fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
477	    ws: &Workspace<'_, R, D>,
478	    spec: &str,
479	) -> Result<bool, GraphError> {
480	    let output = ws
481	        .runner
482	        .run("git", &["rev-parse", "--verify", "--quiet", spec], &ws.root)
483	        .map_err(GraphError::Command)?;
484	    match output.exit_code {
485	        Some(0) => Ok(true),
486	        Some(1) => Ok(false),
487	        exit_code => Err(GraphError::Command(callisto_model::CommandError::Failed {
488	            program: "git".to_string(),
489	            exit_code,
490	            stderr: output.stderr,
491	        })),
492	    }
493	}
