495	/// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
496	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
497	    ws: &Workspace<'_, R, D>,
498	    head: &str,
499	) -> Result<bool, GraphError> {
500	    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
501	    let spec = format!("{head}:{dir}");
502	    if !head_object_exists(ws, &spec)? {
503	        // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
504	        return Ok(false);
505	    }
506	    let output = ws
507	        .runner
508	        .run("git", &["ls-tree", "--name-only", &spec], &ws.root)
509	        .map_err(GraphError::Command)?;
510	    if !output.success() {
511	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
512	            program: "git".to_string(),
513	            exit_code: output.exit_code,
514	            stderr: output.stderr,
515	        }));
516	    }
517	    Ok(output.stdout.lines().any(|name| {
518	        let name = name.trim();
519	        name.ends_with(".md") && name != "README.md"
520	    }))
521	}
