568	/// The paths that differ from `HEAD` in the working tree or the index, and those that differ in the index alone.
569	struct SourceChanges {
570	    changed: BTreeSet<String>,
571	    staged: BTreeSet<String>,
572	}
573	
574	impl SourceChanges {
575	    fn since<R: CommandRunner, D: DependencyResolver>(
576	        ws: &Workspace<'_, R, D>,
577	        head: &str,
578	    ) -> Result<Self, GraphError> {
579	        let mut changed = BTreeSet::new();
580	        let mut staged = BTreeSet::new();
581	        let working_tree = vec!["diff", "--name-only", "-z", head];
582	        let index = vec!["diff", "--cached", "--name-only", "-z", head];
583	        for (args, is_index) in [(working_tree, false), (index, true)] {
584	            let output = ws.runner.run("git", &args, &ws.root).map_err(GraphError::Command)?;
585	            if !output.success() {
586	                return Err(GraphError::Command(callisto_model::CommandError::Failed {
587	                    program: "git".to_string(),
588	                    exit_code: output.exit_code,
589	                    stderr: output.stderr,
590	                }));
591	            }
592	            let paths = output
593	                .stdout
594	                .split('\0')
595	                .filter(|path| !path.is_empty())
596	                .map(str::to_owned);
597	            if is_index {
598	                let paths: Vec<String> = paths.collect();
599	                staged.extend(paths.iter().cloned());
600	                changed.extend(paths);
601	            } else {
602	                changed.extend(paths);
603	            }
604	        }
605	        Ok(SourceChanges { changed, staged })
606	    }
607	}
