609	/// [`version_source_paths`], remembered per manifest.
610	fn version_sources<R: CommandRunner, D: DependencyResolver>(
611	    ws: &Workspace<'_, R, D>,
612	    head: &str,
613	    changed: &SourceChanges,
614	    decl: &callisto_model::ManifestDecl,
615	    memo: &mut HashMap<std::path::PathBuf, Vec<String>>,
616	) -> Result<Vec<String>, GraphError> {
617	    if let Some(known) = memo.get(&decl.path) {
618	        return Ok(known.clone());
619	    }
620	    let sources = version_source_paths(ws, head, changed, decl)?;
621	    memo.insert(decl.path.clone(), sources.clone());
622	    Ok(sources)
623	}
