625	/// Every path whose staged change could alter the effective version of `decl`: its own manifest and, for Cargo, each
626	/// manifest that could be the workspace root it inherits from. That includes the workspace the package names in the
627	/// working tree, and, when its own manifest has changed since `HEAD`, the one it named at `HEAD` and in the index.
628	fn version_source_paths<R: CommandRunner, D: DependencyResolver>(
629	    ws: &Workspace<'_, R, D>,
630	    head: &str,
631	    changed: &SourceChanges,
632	    decl: &callisto_model::ManifestDecl,
633	) -> Result<Vec<String>, GraphError> {
634	    let own = super::release_decision::normalized_git_path(&decl.path)?;
635	    let mut sources = vec![own.clone()];
636	    if decl.ecosystem() == callisto_model::Ecosystem::Cargo {
637	        for candidate in callisto_manifests::workspace_manifest_candidates(&ws.root, &decl.path)? {
638	            sources.push(super::release_decision::normalized_git_path(&candidate)?);
639	        }
640	        if changed.changed.contains(&own) {
641	            for text in [manifest_blob_at(ws, head, &own)?, manifest_blob_in_index(ws, &own)?]
642	                .into_iter()
643	                .flatten()
644	            {
645	                if let Some(named) = callisto_manifests::named_workspace_manifest(&decl.path, &text)? {
646	                    sources.push(super::release_decision::normalized_git_path(&named)?);
647	                }
648	            }
649	        }
650	    }
651	    Ok(sources)
652	}
