654	/// Manifest text by normalized path, fetched at most once per path.
655	type ManifestTexts = RefCell<HashMap<String, Option<String>>>;
656	
657	fn cached_text(
658	    texts: &ManifestTexts,
659	    path: &std::path::Path,
660	    fetch: impl FnOnce(&str) -> Result<Option<String>, GraphError>,
661	) -> Result<Option<String>, GraphError> {
662	    let key = super::release_decision::normalized_git_path(path)?;
663	    if let Some(text) = texts.borrow().get(&key) {
664	        return Ok(text.clone());
665	    }
666	    let text = fetch(&key)?;
667	    texts.borrow_mut().insert(key, text.clone());
668	    Ok(text)
669	}
