671	fn manifest_version_at<R: CommandRunner, D: DependencyResolver>(
672	    ws: &Workspace<'_, R, D>,
673	    head: &str,
674	    path: &str,
675	    texts: &ManifestTexts,
676	    reads: &mut callisto_manifests::WorkspaceReads,
677	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
678	    let path = std::path::Path::new(path);
679	    let Ok(format) = callisto_model::ManifestFormat::from_path(path) else {
680	        return Ok(None);
681	    };
682	    let at_head = |other: &std::path::Path| cached_text(texts, other, |key| manifest_blob_at(ws, head, key));
683	    let Some(source) = at_head(path)? else {
684	        return Ok(None);
685	    };
686	    callisto_manifests::read_effective_version(format, &source, path, reads, at_head)
687	}
