689	/// The version `path` has in the index; manifests it inherits from that the index lacks are read from `head`.
690	fn manifest_version_in_index<R: CommandRunner, D: DependencyResolver>(
691	    ws: &Workspace<'_, R, D>,
692	    head: &str,
693	    path: &str,
694	    texts: &ManifestTexts,
695	    reads: &mut callisto_manifests::WorkspaceReads,
696	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
697	    let manifest_path = std::path::Path::new(path);
698	    let Ok(format) = callisto_model::ManifestFormat::from_path(manifest_path) else {
699	        return Ok(None);
700	    };
701	    let Some(source) = manifest_blob_in_index(ws, path)? else {
702	        return Ok(None);
703	    };
704	    let in_index_or_head = |other: &std::path::Path| {
705	        cached_text(texts, other, |key| match manifest_blob_in_index(ws, key)? {
706	            Some(text) => Ok(Some(text)),
707	            None => manifest_blob_at(ws, head, key),
708	        })
709	    };
710	    callisto_manifests::read_effective_version(format, &source, manifest_path, reads, in_index_or_head)
711	}
712	
713	/// Platform manifest version writes and owner `optionalDependencies` pin updates
714	/// for every owner with a target version in `targets`. Sources: each owner's
715	/// attached platform manifests, plus `[[fixed-group]]`
716	/// platform members.
717	pub(crate) fn platform_version_writes<R: CommandRunner, D: DependencyResolver>(
718	    ws: &Workspace<'_, R, D>,
719	    targets: &std::collections::BTreeMap<callisto_model::PackageId, callisto_model::Version>,
720	) -> Result<(Vec<PlatformWrite>, Vec<crate::plan::OptionalDepUpdate>), GraphError> {
721	    let open_ctx = OpenContext::for_workspace_root(&ws.root)?;
722	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
723	
724	    let mut members: Vec<(&callisto_model::PackageId, &std::path::Path, &str)> = Vec::new();
725	    for pkg in ws.graph.packages() {
726	        members.extend(
727	            ws.identity
728	                .attached_platforms(pkg)
729	                .map(|(name, path)| (&pkg.id, path, name)),
730	        );
731	    }
732	    for group in ws.config.groups.fixed.values() {
733	        for member in group.members(GroupMemberKind::PlatformManifest) {
734	            if let GroupMember::PlatformManifest { owner, path, name, .. } = member {
735	                members.push((owner, path, name));
736	            }
737	        }
738	    }
739	
740	    let mut seen = HashSet::new();
741	    let mut platform_writes = Vec::new();
742	    let mut optional_dep_map: std::collections::BTreeMap<std::path::PathBuf, Vec<(String, callisto_model::Version)>> =
743	        std::collections::BTreeMap::new();
744	    for (owner, path, name) in members {
745	        let Some(to) = targets.get(owner) else {
746	            continue;
747	        };
748	        if !seen.insert(path) {
749	            continue;
750	        }
751	        let fmt = callisto_model::ManifestFormat::from_path(path)?;
752	        let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
753	        let handle = open(&decl, &open_ctx)?;
754	        let current = handle.current_version()?;
755	        platform_writes.push(PlatformWrite {
756	            manifest: path.to_path_buf(),
757	            version: to.clone(),
758	            from: current,
759	        });
760	
761	        // A dual-manifest owner declares its platforms in package.json, not Cargo.toml.
762	        for owner_decl in pkg_map.get(owner).into_iter().flat_map(|p| p.canonical_manifests()) {
763	            let owner_fmt = callisto_model::ManifestFormat::from_path(&owner_decl.path)?;
764	            let owner_manifest_decl =
765	                callisto_model::ManifestDecl::new(owner_decl.path.clone(), ManifestRole::Canonical, owner_fmt)?;
766	            // Cached: owner manifest is shared across every platform target under it.
767	            let owner_handle = crate::manifest_cache::open_cached(&ws.manifest_cache, &owner_manifest_decl, &open_ctx)?;
768	            if owner_handle
769	                .iter_dependencies()
770	                .any(|dep| dep.kind == callisto_model::DepKind::Optional && dep.name == name)
771	            {
772	                optional_dep_map
773	                    .entry(owner_decl.path.clone())
774	                    .or_default()
775	                    .push((name.to_string(), to.clone()));
776	                break;
777	            }
778	        }
779	    }
780	    let optional_dep_updates = optional_dep_map
781	        .into_iter()
782	        .map(|(manifest, updates)| crate::plan::OptionalDepUpdate { manifest, updates })
783	        .collect();
784	    Ok((platform_writes, optional_dep_updates))
785	}
